import asyncio
from playwright.async_api import async_playwright

URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"

async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch()
        pg = await b.new_page(viewport={"width": 1440, "height": 900})
        await pg.goto(URL, wait_until="load", timeout=20000)
        await pg.wait_for_timeout(500)
        # find scrollY range near the exit by locating #process bottom
        info = await pg.evaluate("""() => {
          const stick = document.querySelector('.process-stick');
          const lis = document.querySelectorAll('.process-steps li');
          const li07 = lis[lis.length-1];
          const band07 = li07.querySelector('.step-band');
          return {stickTop0: stick.getBoundingClientRect().top, scrollY: window.scrollY};
        }""")
        print("initial", info)
        for y in range(13600, 14400, 20):
            await pg.evaluate(f"window.scrollTo(0,{y})")
            await pg.wait_for_timeout(30)
            r = await pg.evaluate("""() => {
              const stick = document.querySelector('.process-stick');
              const lis = document.querySelectorAll('.process-steps li');
              const li07 = lis[lis.length-1];
              const band07 = li07.querySelector('.step-band');
              const sr = stick.getBoundingClientRect();
              const br = band07.getBoundingClientRect();
              const lr = li07.getBoundingClientRect();
              return {stickTop: sr.top, stickBottom: sr.bottom, bandTop: br.top, bandBottom: br.bottom, liTop: lr.top, liBottom: lr.bottom};
            }""")
            print(y, r)
        await b.close()

asyncio.run(main())

