import asyncio
from playwright.async_api import async_playwright

URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"

async def find_release(pg):
    # binary-ish scan in 10px steps between 13000 and 15500 for stick release
    lo, hi = 13000, 15500
    stick_release = None
    band_release = None
    for y in range(lo, hi, 10):
        await pg.evaluate(f"window.scrollTo(0,{y})")
        r = await pg.evaluate("""() => {
          const stick = document.querySelector('.process-stick');
          const lis = document.querySelectorAll('.process-steps li');
          const li07 = lis[lis.length-1];
          const band07 = li07.querySelector('.step-band');
          return {stickTop: stick.getBoundingClientRect().top, bandTop: band07.getBoundingClientRect().top};
        }""")
        if stick_release is None and r['stickTop'] < 215:
            stick_release = y
        if band_release is None and r['bandTop'] < -1:
            band_release = y
        if stick_release and band_release:
            break
    return stick_release, band_release

async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch()
        pg = await b.new_page(viewport={"width": 1440, "height": 900})
        await pg.goto(URL, wait_until="load", timeout=20000)
        await pg.wait_for_timeout(500)
        for pb in ["60svh", "70svh", "80svh", "90svh", "100svh"]:
            await pg.evaluate(f"""() => {{
              let tag = document.getElementById('__tune');
              if (!tag) {{ tag = document.createElement('style'); tag.id='__tune'; document.head.appendChild(tag); }}
              tag.textContent = '.process-steps{{padding-bottom:{pb} !important;}}';
            }}""")
            await pg.wait_for_timeout(200)
            sr, br = await find_release(pg)
            print(pb, "stick_release=", sr, "band_release=", br, "gap=", (br-sr) if (sr and br) else None)
        await b.close()

asyncio.run(main())

