/* PLAN 048 D. Jätten på kortets material: svart plåt, papperets bläck,
   samma hårlinjekant som plåten i heron. Tokenbyte som i C. */
#giant-section{
  --bg: var(--c-black); --ink: var(--c-paper);
  --c-line-on-paper: var(--hairline-dark);
  border:1px solid var(--frame-line);}
/* PLAN 049 fix 6 (Astra material_fixes #6, P04). Ett bleed vänsterut,
   samma teknik som .thesis-figure redan använder (negativ margin +
   motsvarande breddökning), läsande jättens EGEN --scrub (redan
   beräknad två rader ovan ur samma akts --sc-ps, ingen ny variabel).
   margin-top höjt (270->820) efter P03: en obledad tes (bredare i
   denna runda, se .thesis-figure) och en obledad jätte delade skärm
   medan tesens svans fortfarande syntes - rubriken skar rakt genom
   tesbildens kant (skärmbild, scrollY 3600). 820px håller jätten
   osynlig tills tesen rullat bort helt (scrollY ~3900). 44vw (höjt
   från 38) så bredden hinner över 80%vw INNAN rubriken (h1.giant, inte
   .giant-head-omslaget som även räknar in undertexten) rullar ur
   synfältet - uppmätt scrollY 4330: rubrik fortfarande synlig
   (h1Bottom +39px), bredd 82%vw. Ingen kollision tes/rubrik i hela
   övergångsspannet 3200-4300 (uppmätt, rect-overlap X och Y). */
@media (min-width:901px){
  .panel-giant{
    margin-top:820px;
    margin-left:calc(-1 * var(--scrub) * 44vw);
    width:calc(100% + var(--scrub) * 44vw);}
}
#giant-section .giant-sub,#giant-section .ledger-body p{
  color:color-mix(in srgb, var(--c-paper) 72%, var(--c-black));}
